def solve():
    s = sys.stdin.readline().strip()
    if not s:
        return "NO"

    mirror_chars = {'A', 'H', 'I', 'M', 'O', 'T', 'U', 'V', 'W', 'X', 'Y'}

    # Check each character
    for char in s:
        if char not in mirror_chars:
            return "NO"

    # Check symmetry: the i-th character from start must equal the i-th from end
    # Since all valid mirror characters are symmetric themselves, we just need to check that the string is a palindrome
    if s == s[::-1]:
        return "YES"
    else:
        return "NO"

